#include <stdio.h>

int main() {
    int a[] = {3, 1, 4, 1, 5, 9};
    int prefix[7] = {0};
    for (int i = 0; i < 6; i++) {
        prefix[i + 1] = prefix[i] + a[i];
    }
    int left = 1, right = 4;
    printf("Sum of a[%d..%d] = %d\n", left, right, prefix[right + 1] - prefix[left]);
    return 0;
}
